function Panel({ title, subtitle, children, action }: { title: string; subtitle: string; children: React.ReactNode; action?: React.ReactNode }) { return <section className="card min-w-0 p-4 sm:p-5"><div className="mb-5 flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><h3 className="font-bold text-white">{title}</h3><p className="mt-1 text-xs text-slate-400">{subtitle}</p></div>{action}</div>{children}{title === 'Fuentes de catálogos' && <p className="mt-2 text-xs text-slate-500">{PDF_SIZE_HELP} por archivo. No OCR productivo.</p>}</section>; }
function EmptyState({ text }: { text: string }) { return <div className="rounded-xl border border-dashed border-white/15 p-8 text-center text-sm text-slate-400 sm:p-10">{text}</div>; }
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block text-xs font-semibold text-slate-300"><span className="mb-1.5 block">{label}</span>{children}</label>; }
function Badge({ value }: { value: string }) { const color = /pagado|Llegó|Recibido|received|Confirmado|Aprobado|Activo|Extraído/.test(value) ? 'badge-green' : /vencido|Faltante|shortage|Sobrante|Rechazado|Error|Inactivo|Desactivado/.test(value) ? 'badge-red' : 'badge-amber'; return <span className={color}>{value}</span>; }
function Metric({ title, value, note, color = 'cyan', icon = <ArrowTrendingUpIcon className="h-5 w-5" />, onClick }: { title: string; value: string; note: string; color?: string; icon?: React.ReactNode; onClick?: () => void }) { const colors: Record<string, string> = { cyan: 'bg-cyan-400/15 text-cyan-300', green: 'bg-emerald-400/15 text-emerald-300', amber: 'bg-amber-400/15 text-amber-300', red: 'bg-red-400/15 text-red-300' }; const body = <><span className={`inline-flex rounded-lg p-2 ${colors[color]}`}>{icon}</span><div className="mt-3 truncate text-xl font-bold tracking-tight text-white sm:mt-4 sm:text-2xl">{value}</div><div className="mt-1 text-sm font-semibold text-slate-300">{title}</div><div className="mt-2 truncate text-xs text-slate-500">{note}</div></>; return onClick ? <button type="button" onClick={onClick} className="card block min-w-0 p-4 text-left transition hover:border-cyan-300/40 sm:p-5">{body}</button> : <div className="card min-w-0 p-4 sm:p-5">{body}</div>; }

export function Dashboard({ section, onNavigate, onOpenMenu, demo, cloud, installPromptAvailable, installed, onInstallPrompt }: { section: Section; onNavigate: (section: Section) => void; onOpenMenu: () => void; demo: Demo; cloud: CloudSync; installPromptAvailable: boolean; installed: boolean; onInstallPrompt: () => Promise<void> }) {
  const [toast, setToast] = useState(''); const [online, setOnline] = useState(true); const [referenceDate, setReferenceDate] = useState(DEMO_TODAY); const [greeting, setGreeting] = useState('');
  useEffect(() => { const now = new Date(); setReferenceDate(getLocalDateISO(now)); setGreeting(currentGreeting(now)); }, []);
  useEffect(() => { const update = () => setOnline(navigator.onLine); update(); window.addEventListener('online', update); window.addEventListener('offline', update); return () => { window.removeEventListener('online', update); window.removeEventListener('offline', update); }; }, []);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 4000); return () => window.clearTimeout(timer); }, [toast]);
  useEffect(() => { document.title = section === 'Inicio' ? 'Control de Abastecimiento' : `${sectionLabels[section]} · Control de Abastecimiento`; }, [section]);
  useEffect(() => { const generated = buildAlerts(demo.state, referenceDate, demo.state.alerts); if (JSON.stringify(generated) !== JSON.stringify(demo.state.alerts)) demo.update((current) => ({ ...current, alerts: generated })); }, [demo, demo.state.expiries, demo.state.orders, demo.state.products, demo.state.alertPreferences, demo.state.alerts, referenceDate]);
  const notify = useCallback((message: string) => setToast(message), []);
  const activeUser = demo.state.users.find((user) => user.id === demo.state.activeUserId && user.active) || demo.state.users.find((user) => user.active);
  const userName = activeUser?.name || 'Sin usuario';
  const exportPayments = () => { const rows = demo.state.payments.filter((p) => !p.cancelled).map((p) => [p.id, supplierName(demo.state.suppliers, p.supplierId), p.orderId || '', p.amount, p.date, p.method, p.cashBox || '', p.status, p.reference, p.responsible || '']); downloadCsv('pagos-control-abastecimiento.csv', ['ID', 'Proveedor', 'Pedido', 'Monto', 'Fecha', 'Método', 'Caja', 'Estado', 'Referencia', 'Responsable'], rows); notify('CSV de pagos descargado'); };
  const activeAlerts = useMemo(() => latestPerSource(demo.state.alerts.filter((alert) => effectiveStatus(alert, referenceDate) === 'activa')), [demo.state.alerts, referenceDate]);
  const [cloudTipHidden, setCloudTipHidden] = useState(false);
  useEffect(() => { try { setCloudTipHidden(window.sessionStorage.getItem('zavryon-cloud-tip') === '1'); } catch { /* Show the tip. */ } }, []);
  const hideCloudTip = () => { setCloudTipHidden(true); try { window.sessionStorage.setItem('zavryon-cloud-tip', '1'); } catch { /* Hidden for this view only. */ } };
  useEffect(() => { if (!demo.state.alertPreferences.browser || !('Notification' in window) || Notification.permission !== 'granted') return; const pending = activeAlerts.find((alert) => !demo.state.alertPreferences.notifiedKeys.includes(alert.key)); if (!pending) return; new Notification('ZAVRYON SYSTEMS', { body: pending.title, icon: '/icon-192.png' }); demo.update((current) => ({ ...current, alertPreferences: { ...current.alertPreferences, notifiedKeys: [...current.alertPreferences.notifiedKeys, pending.key].slice(-500) } })); }, [activeAlerts, demo]);
  const content = section === 'Inicio' ? <Home state={demo.state} alerts={activeAlerts} onNavigate={onNavigate} /> : section === 'Abastecimiento' ? <Supply state={demo.state} update={demo.update} notify={notify} onNavigate={onNavigate} userName={userName} /> : section === 'Pedidos' ? <Orders state={demo.state} update={demo.update} notify={notify} onNavigate={onNavigate} userName={userName} /> : section === 'Nuevo pedido' ? <NewOrder state={demo.state} update={demo.update} notify={notify} onNavigate={onNavigate} /> : section === 'Recepcion' ? <Reception state={demo.state} update={demo.update} notify={notify} userName={userName} /> : section === 'Proveedores llegados' ? <Arrivals state={demo.state} onNavigate={onNavigate} /> : section === 'Proveedores' ? <Suppliers state={demo.state} update={demo.update} notify={notify} /> : section === 'Catalogo' ? <Catalog state={demo.state} update={demo.update} notify={notify} /> : section === 'Fuentes' ? <Sources state={demo.state} update={demo.update} notify={notify} /> : section === 'Vencimientos' ? <AlertExpiries state={demo.state} update={demo.update} notify={notify} onNavigate={onNavigate} /> : section === 'Agenda' ? <AlertAgenda state={demo.state} update={demo.update} notify={notify} onNavigate={onNavigate} /> : section === 'Notificaciones' ? <Notifications state={demo.state} update={demo.update} notify={notify} onNavigate={onNavigate} /> : section === 'Historial' ? <History state={demo.state} /> : section === 'Economia' ? <Economy state={demo.state} onNavigate={onNavigate} /> : section === 'Pagos' ? <Payments state={demo.state} update={demo.update} notify={notify} exportCsv={exportPayments} userName={userName} /> : section === 'Usuarios' ? <Users state={demo.state} update={demo.update} notify={notify} /> : <Settings demo={demo} cloud={cloud} notify={notify} installPromptAvailable={installPromptAvailable} installed={installed} onInstallPrompt={onInstallPrompt} />;
  return <main className="min-w-0 flex-1">
    <header className="sticky top-0 z-20 border-b border-white/10 bg-petroleum-950/90 backdrop-blur">
      <div className="mx-auto flex max-w-[1500px] items-center gap-3 px-4 py-3 sm:px-6 lg:px-10">
        <button type="button" onClick={onOpenMenu} aria-label="Abrir menú" aria-controls="app-sidebar" className="icon-button -ml-2 text-white lg:hidden"><Bars3Icon className="h-6 w-6" /></button>
        <LogoMark className="hidden h-9 w-9 shrink-0 sm:block lg:hidden" />
        <div className="min-w-0 flex-1">
          <div className="truncate text-sm font-bold text-white sm:text-base">{demo.state.config.clientName}</div>
          <div className="truncate text-xs text-slate-400"><span className="inline-block first-letter:uppercase">{formatDateEs(referenceDate, { weekday: 'long', day: 'numeric', month: 'long' })}</span>{greeting && <span className="hidden sm:inline"> · {greeting}{activeUser ? `, ${activeUser.name}` : ''}</span>}</div>
        </div>
        <span className={`hidden items-center gap-1 text-xs font-semibold md:flex ${online ? 'text-emerald-300' : 'text-amber-300'}`} role="status">{online ? <SignalIcon className="h-4 w-4" /> : <SignalSlashIcon className="h-4 w-4" />}{online ? 'En línea' : 'Sin conexión'}</span>
        <CloudBadge cloud={cloud} onClick={() => onNavigate('Configuración')} />
        <button type="button" onClick={() => onNavigate('Notificaciones')} aria-label={`Notificaciones${activeAlerts.length ? ` (${activeAlerts.length} activas)` : ''}`} className="icon-button relative border border-white/10 text-slate-300 hover:text-cyan-300"><BellAlertIcon className="h-5 w-5" />{activeAlerts.length > 0 && <span className="absolute -right-1 -top-1 min-w-5 rounded-full bg-amber-400 px-1 text-center text-[10px] font-bold leading-5 text-amber-950">{activeAlerts.length}</span>}</button>
        <button type="button" onClick={() => onNavigate('Nuevo pedido')} className="button-primary" aria-label="Nuevo pedido"><PlusIcon className="h-5 w-5" /><span className="hidden sm:inline">Nuevo pedido</span></button>
      </div>
    </header>
    {!online && <div role="status" className="bg-amber-500/15 px-4 py-2 text-center text-xs font-semibold text-amber-200">Sin conexión: podés seguir trabajando, los datos se guardan en este dispositivo.</div>}
    <div id="contenido" tabIndex={-1} className="mx-auto max-w-[1500px] px-4 py-6 outline-none sm:px-6 lg:px-10 lg:py-8">
      <div className="mb-6"><p className="mb-1 text-xs font-semibold uppercase tracking-widest text-amber-300">{demo.state.config.companyName}</p><h2 className="text-2xl font-bold tracking-tight text-white sm:text-3xl">{sectionLabels[section]}</h2></div>
      {content}
    </div>
    <CloudConflictDialog cloud={cloud} />
    {cloud.status === 'sin-sesion' && section === 'Inicio' && !cloudTipHidden && <div role="status" className="fixed bottom-4 left-4 right-4 z-30 mx-auto flex max-w-xl flex-wrap items-center justify-between gap-3 rounded-2xl border border-amber-300/30 bg-petroleum-900 p-4 shadow-panel sm:left-auto sm:right-6"><p className="min-w-[12rem] flex-1 text-sm text-amber-100">Tus datos están solo en este dispositivo. Iniciá sesión para guardarlos en la nube.</p><div className="flex w-full justify-end gap-2 sm:w-auto"><button type="button" className="button-secondary" onClick={hideCloudTip}>Más tarde</button><button type="button" className="button-primary" onClick={() => onNavigate('Configuración')}>Guardar en la nube</button></div></div>}
    {toast && <div role="status" aria-live="polite" className="toast"><CheckCircleIcon className="h-5 w-5 shrink-0 text-cyan-300" /><span className="min-w-0 flex-1">{toast}</span><button type="button" className="text-slate-400 hover:text-white" aria-label="Cerrar aviso" onClick={() => setToast('')}><XMarkIcon className="h-4 w-4" /></button></div>}
  </main>;
}

function Home({ state, alerts, onNavigate }: { state: State; alerts: AppAlert[]; onNavigate: (s: Section) => void }) {
  const totals = finance(state);
  const open = state.orders.filter((order) => isOrderOpen(order));
  const lowStock = state.products.filter((product) => product.active && needsRestock(product));
  const missing = lowStock.filter((product) => stockStatus(product) === 'faltante').length;
  const alertSection = (alert: AppAlert): Section => alert.kind === 'vencimiento' ? 'Vencimientos' : alert.kind === 'stock' ? 'Abastecimiento' : 'Pedidos';
  return <>
    <div className="grid grid-cols-2 gap-3 sm:gap-4 xl:grid-cols-4">
      <Metric title="Pedidos abiertos" value={String(open.length)} note={`${open.filter((order) => orderStage(order.status) === 'en-curso').length} en curso`} icon={<ArrowTrendingUpIcon className="h-5 w-5" />} onClick={() => onNavigate('Pedidos')} />
      <Metric title="Stock con alerta" value={String(lowStock.length)} note={missing ? `${missing} sin stock` : 'Todo en orden'} color={lowStock.length ? 'red' : 'green'} icon={<RectangleStackIcon className="h-5 w-5" />} onClick={() => onNavigate('Abastecimiento')} />
      <Metric title="Total comprado" value={money(totals.purchased)} note={`${money(totals.received)} recibido`} color="amber" onClick={() => onNavigate('Economia')} />
      <Metric title="Saldo pendiente" value={money(totals.balance)} note={`${money(totals.paid)} pagado`} color="red" icon={<WalletIcon className="h-5 w-5" />} onClick={() => onNavigate('Pagos')} />
    </div>
    <div className="mt-6"><SeasonHighlights state={state} onOpen={() => { openSupplyTab('temporada'); onNavigate('Abastecimiento'); }} /></div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.65fr_1fr]">
      <Panel title="Pedidos recientes" subtitle="Compra, estado, recepción y pago en un mismo vistazo" action={<button type="button" onClick={() => onNavigate('Pedidos')} className="link-button">Ver todos <ChevronRightIcon className="h-4 w-4" /></button>}><OrderTable state={state} /></Panel>
      <Panel title="Alertas y acciones" subtitle={alerts.length ? `${alerts.length} alerta(s) activa(s)` : 'Lo que necesita tu atención'} action={alerts.length > 5 ? <button type="button" onClick={() => onNavigate('Notificaciones')} className="link-button">Ver todas <ChevronRightIcon className="h-4 w-4" /></button> : undefined}>
        {alerts.length ? <ul className="space-y-2">{[...alerts].sort((a, b) => (a.priority === 'alta' ? 0 : 1) - (b.priority === 'alta' ? 0 : 1)).slice(0, 5).map((alert) => <li key={alert.id}><button type="button" onClick={() => onNavigate(alertSection(alert))} className="flex w-full gap-3 rounded-xl border border-white/10 p-3 text-left transition hover:border-cyan-300/40"><span className={`mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-full ${alert.priority === 'alta' ? 'bg-red-400/15 text-red-300' : 'bg-amber-400/15 text-amber-300'}`}><ExclamationTriangleIcon className="h-5 w-5" /></span><span className="min-w-0"><span className="block text-sm font-bold text-white">{alert.title}</span><span className="mt-0.5 block text-xs leading-5 text-slate-400">{alert.detail}</span></span><ChevronRightIcon className="ml-auto h-4 w-4 shrink-0 self-center text-slate-500" /></button></li>)}</ul> : <EmptyState text="Sin alertas activas. ¡Todo en orden!" />}
      </Panel>
    </div>
  </>;
}
function OrderTable({ state }: { state: State }) { const recent = [...state.orders].reverse().slice(0, 6); return recent.length ? <><ul className="space-y-2 md:hidden">{recent.map((o) => { const stage = orderStage(o.status); return <li key={o.id} className="flex items-center justify-between gap-3 rounded-xl border border-white/10 p-3"><div className="min-w-0"><div className="truncate font-semibold text-white">{o.id} · {supplierName(state.suppliers, o.supplierId)}</div><div className="text-xs text-slate-400">{money(orderTotal(o))}</div></div><span className={stageBadge[stage]}>{stageLabels[stage]}</span></li>; })}</ul><div className="hidden overflow-x-auto md:block"><table className="data-table"><thead><tr><th>Pedido</th><th>Proveedor</th><th>Total</th><th>Estado</th><th>Pago</th></tr></thead><tbody>{recent.map((o) => { const stage = orderStage(o.status); return <tr key={o.id}><td className="font-bold text-white">{o.id}</td><td>{supplierName(state.suppliers, o.supplierId)}</td><td className="whitespace-nowrap">{money(orderTotal(o))}</td><td><span className={stageBadge[stage]}>{stageLabels[stage]}</span></td><td><Badge value={paymentLabel(state, o.id)} /></td></tr>; })}</tbody></table></div></> : <EmptyState text="Todavía no hay pedidos." />; }
function Orders({ state, update, notify, onNavigate, userName }: { state: State; update: Mutate; notify: (m: string) => void; onNavigate: (s: Section) => void; userName: string }) {
  const [printOrderId, setPrintOrderId] = useState<string | null>(null); const [detailOrderId, setDetailOrderId] = useState<string | null>(null); const [editing, setEditing] = useState<Order | null>(null);
  const [filter, setFilter] = useState<'todos' | OrderStage>('todos'); const [query, setQuery] = useState('');
  const counts = state.orders.reduce((acc, order) => { const stage = orderStage(order.status); acc[stage] = (acc[stage] || 0) + 1; return acc; }, {} as Partial<Record<OrderStage, number>>);
  const filters: ('todos' | OrderStage)[] = ['todos', 'preparado', 'enviado', 'en-curso', 'en-recepcion', 'recibido', 'cancelado'];
  const rows = [...state.orders].reverse().filter((o) => (filter === 'todos' || orderStage(o.status) === filter) && (!query.trim() || `${o.id} ${supplierName(state.suppliers, o.supplierId)} ${o.requester || ''} ${o.responsible}`.toLowerCase().includes(query.trim().toLowerCase())));
  const setStatus = (order: Order, status: Order['status'], message: string, note?: string) => { update((current) => ({ ...current, orders: current.orders.map((item) => item.id === order.id ? withStatus(item, status, userName, note) : item) })); notify(message); };
  const messageFor = (order: Order) => orderMessage(order, { clientName: state.config.clientName, supplier: state.suppliers.find((s) => s.id === order.supplierId), products: state.products, supplierProducts: state.supplierProducts, includePrices: true });
  const sendWhatsapp = (order: Order) => { const supplier = state.suppliers.find((s) => s.id === order.supplierId); window.open(whatsappUrl(supplier?.phone || '', messageFor(order)), '_blank', 'noopener,noreferrer'); if (orderStage(order.status) === 'preparado') setStatus(order, 'Enviado', `${order.id} enviado por WhatsApp a ${supplier?.name || 'proveedor'}`, 'WhatsApp'); if (!supplier?.phone) notify('El proveedor no tiene teléfono cargado: elegí el contacto en WhatsApp'); };
  const share = async (order: Order) => { const text = messageFor(order); try { if (navigator.share) { await navigator.share({ title: `Pedido ${order.id}`, text }); } else { await navigator.clipboard.writeText(text); notify('Pedido copiado: pegalo en el mensaje o mail al proveedor'); } if (orderStage(order.status) === 'preparado') setStatus(order, 'Enviado', `${order.id} marcado como enviado`, 'Compartido'); } catch { /* Share sheet dismissed. */ } };
  const receive = (order: Order) => { try { window.sessionStorage.setItem('zavryon-receive-order', order.id); } catch { /* Storage unavailable: reception opens on the first pending order. */ } onNavigate('Recepcion'); };
  const cancel = (order: Order) => { const reason = window.prompt(`¿Cancelar ${order.id}? Escribí el motivo (opcional):`); if (reason === null) return; setStatus(order, 'Cancelado', `${order.id} cancelado`, reason.trim() || undefined); };
  const actions = (o: Order) => { const stage = orderStage(o.status); return <div className="flex flex-wrap gap-2">
    {(stage === 'preparado' || stage === 'enviado') && <button type="button" onClick={() => sendWhatsapp(o)} className="button-secondary" title="Enviar el pedido por WhatsApp al proveedor"><ChatBubbleLeftRightIcon className="h-4 w-4" /> WhatsApp</button>}
    {canConfirm(o) && <button type="button" onClick={() => setStatus(o, 'En curso', `${o.id} confirmado: queda en curso`)} className="button-primary"><CheckCircleIcon className="h-4 w-4" /> Confirmar pedido</button>}
    {(stage === 'en-curso' || stage === 'en-recepcion') && <button type="button" onClick={() => receive(o)} className="button-primary"><InboxArrowDownIcon className="h-4 w-4" /> Recibir</button>}
    <button type="button" onClick={() => setPrintOrderId(o.id)} className="button-secondary"><DocumentArrowDownIcon className="h-4 w-4" /> PDF</button>
    <button type="button" onClick={() => void share(o)} className="button-secondary" aria-label={`Compartir ${o.id}`}><ShareIcon className="h-4 w-4" /></button>
    <button type="button" onClick={() => setDetailOrderId(o.id)} className="button-secondary">Ver detalle</button>
    {isOrderOpen(o) && <button type="button" onClick={() => setEditing(structuredClone(o))} className="button-secondary" aria-label={`Editar ${o.id}`}><PencilSquareIcon className="h-4 w-4" /></button>}
    {canCancel(o) && <button type="button" onClick={() => cancel(o)} className="icon-button text-red-300" aria-label={`Cancelar ${o.id}`}><XMarkIcon className="h-4 w-4" /></button>}
  </div>; };
  return <>
    <Panel title="Pedidos" subtitle="Armá el pedido antes de que venga el proveedor, envialo por WhatsApp o PDF, confirmalo y recibilo" action={<div className="flex flex-wrap gap-2"><input aria-label="Buscar pedidos" className="field w-full sm:w-52" placeholder="Buscar pedido o proveedor…" value={query} onChange={(e) => setQuery(e.target.value)} /><button type="button" onClick={() => onNavigate('Nuevo pedido')} className="button-primary"><PlusIcon className="h-4 w-4" /> Nuevo</button></div>}>
      <div role="tablist" aria-label="Filtrar por estado" className="tab-list mb-4">{filters.map((item) => <button key={item} type="button" role="tab" aria-selected={filter === item} className="tab" onClick={() => setFilter(item)}>{item === 'todos' ? 'Todos' : stageLabels[item]}{item !== 'todos' && counts[item] ? <span className="tab-count">{counts[item]}</span> : null}</button>)}</div>
      {rows.length ? <><ul className="space-y-3 md:hidden">{rows.map((o) => { const stage = orderStage(o.status); return <li key={o.id} className="rounded-xl border border-white/10 p-4"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="font-bold text-white">{o.id} · {supplierName(state.suppliers, o.supplierId)}</div><div className="mt-1 text-xs text-slate-400">{o.lines.length} artículo(s) · entrega {dateEs(o.expectedDate || '')} · {requesterLabel(o)}</div></div><span className={stageBadge[stage]}>{stageLabels[stage]}</span></div><div className="mt-2 flex items-center justify-between text-sm"><span className="font-semibold text-white">{money(orderTotal(o))}</span><Badge value={paymentLabel(state, o.id)} /></div><div className="mt-3">{actions(o)}</div></li>; })}</ul><div className="hidden overflow-x-auto md:block"><table className="data-table"><thead><tr><th>Pedido</th><th>Proveedor</th><th>Entrega</th><th>Solicitante / solicitado</th><th>Total</th><th>Estado</th><th>Pago</th><th>Acciones</th></tr></thead><tbody>{rows.map((o) => { const stage = orderStage(o.status); return <tr key={o.id}>
        <td className="font-bold text-white">{o.id}<div className="text-xs font-normal text-slate-500">{o.lines.length} artículo(s) · {o.responsible || 'Sin responsable'}</div></td>
        <td>{supplierName(state.suppliers, o.supplierId)}</td>
        <td className="whitespace-nowrap">{dateEs(o.expectedDate || '')}</td>
        <td><div>{requesterLabel(o)}</div><div className="text-xs text-slate-500">{requestedAtLabel(o)}</div></td>
        <td className="whitespace-nowrap">{money(orderTotal(o))}</td>
        <td><span className={stageBadge[stage]}>{stageLabels[stage]}</span></td>
        <td><Badge value={paymentLabel(state, o.id)} /></td>
        <td>{actions(o)}</td>
      </tr>; })}</tbody></table></div></> : <EmptyState text={state.orders.length ? 'No hay pedidos con ese filtro.' : 'No hay pedidos registrados. Creá uno desde “Nuevo pedido” o desde Stock y abastecimiento.'} />}
    </Panel>
    <OrderDetail state={state} orderId={detailOrderId} onClose={() => setDetailOrderId(null)} />
    <OrderPdf state={state} orderId={printOrderId} onClose={() => setPrintOrderId(null)} />
    {editing && <OrderEditor order={editing} state={state} update={update} onClose={() => setEditing(null)} />}
  </>;
}

function OrderTimeline({ order }: { order: Order }) {
  const stage = orderStage(order.status);
  if (stage === 'cancelado') { const event = [...(order.events || [])].reverse().find((item) => item.status === 'Cancelado'); return <p className="rounded-xl border border-red-300/20 bg-red-400/10 p-3 text-sm text-red-200">Pedido cancelado{event ? ` el ${new Date(event.at).toLocaleString('es-AR', { dateStyle: 'short', timeStyle: 'short' })} por ${event.by}` : ''}{event?.note ? ` · ${event.note}` : ''}</p>; }
  const current = timelineStages.indexOf(stage === 'en-recepcion' ? 'en-curso' : stage);
  return <ol className="grid grid-cols-4 gap-2" aria-label="Estado del pedido">{timelineStages.map((item, index) => { const done = index <= current; const at = index === 0 ? (order.requestedAt || order.createdAt) : stageDate(order, item); return <li key={item} className={`rounded-xl border p-3 ${done ? 'border-cyan-300/40 bg-cyan-400/10' : 'border-white/10'}`}><div className={`text-xs font-bold ${done ? 'text-cyan-200' : 'text-slate-500'}`}>{index + 1}. {stageLabels[item]}</div><div className="mt-1 text-[11px] text-slate-400">{done && at ? new Date(at).toLocaleDateString('es-AR', { day: 'numeric', month: 'short' }) : '—'}</div></li>; })}</ol>;
}

function OrderDetail({ state, orderId, onClose }: { state: State; orderId: string | null; onClose: () => void }) { const order = state.orders.find((item) => item.id === orderId); if (!order) return null; const supplier = state.suppliers.find((item) => item.id === order.supplierId); const reception = state.receptions.find((item) => item.orderId === order.id); const payments = state.payments.filter((item) => item.orderId === order.id && !item.cancelled); return <Panel title={`Detalle del pedido ${order.id}`} subtitle="Seguimiento del pedido, recepción y pagos"><div className="mb-5"><OrderTimeline order={order} /></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div><div className="text-xs text-slate-500">Proveedor</div><div className="font-semibold text-white">{supplier?.name || 'Sin proveedor'}</div></div><div><div className="text-xs text-slate-500">Solicitante</div><div className="font-semibold text-white">{requesterLabel(order)}</div></div><div><div className="text-xs text-slate-500">Solicitado en</div><div className="font-semibold text-white">{requestedAtLabel(order)}</div></div><div><div className="text-xs text-slate-500">Responsable</div><div className="font-semibold text-white">{order.responsible || 'Pendiente'}</div></div><div><div className="text-xs text-slate-500">Llegada esperada</div><div className="font-semibold text-white">{dateEs(order.expectedDate)}</div></div><div><div className="text-xs text-slate-500">Recepción</div><div className="font-semibold text-white">{reception?.arrivedAt ? `${dateEs(reception.arrivedAt)} · ${reception.arrivedAt.slice(11, 16)}` : 'Pendiente'}</div></div><div><div className="text-xs text-slate-500">Total</div><div className="font-semibold text-white">{money(orderTotal(order))}</div></div><div><div className="text-xs text-slate-500">Pago</div><div className="font-semibold text-white">{paymentLabel(state, order.id)}</div></div></div><div className="mt-6 overflow-x-auto"><table className="data-table"><thead><tr><th>Producto</th><th>SKU</th><th>Cantidad</th><th>Precio</th><th>Subtotal</th><th>Recibida</th></tr></thead><tbody>{order.lines.map((line) => { const product = state.products.find((item) => item.id === line.productId); const received = reception?.lines.find((item) => item.orderLineId === line.id); return <tr key={line.id}><td className="font-semibold text-white">{product?.name || 'Producto eliminado'}</td><td>{product?.sku || 'Pendiente'}</td><td>{line.quantity}</td><td>{money(line.price)}</td><td>{money(line.price * line.quantity)}</td><td>{received?.received ?? 0}</td></tr>; })}</tbody><tfoot><tr><td colSpan={4}>Total</td><td>{money(orderTotal(order))}</td><td /></tr></tfoot></table></div><div className="mt-5 grid gap-4 md:grid-cols-2"><div className="rounded-xl border border-white/10 p-4"><h4 className="font-bold text-white">Recepción y observaciones</h4><p className="mt-2 text-sm text-slate-300">{order.notes || 'Sin observaciones'}</p>{reception?.lines.length ? <ul className="mt-3 space-y-1 text-xs text-slate-400">{reception.lines.map((line) => <li key={line.id}>{receptionLabels[line.status]} · {line.received}/{line.expected} · {line.note || 'sin nota'}</li>)}</ul> : null}</div><div className="rounded-xl border border-white/10 p-4"><h4 className="font-bold text-white">Pagos asociados</h4>{payments.length ? <ul className="mt-2 space-y-1 text-sm text-slate-300">{payments.map((payment) => <li key={payment.id}>{dateEs(payment.date)} · {money(payment.amount)} · {payment.method} · {payment.status} · {payment.reference || 'sin referencia'}{payment.notes ? ` · ${payment.notes}` : ''}</li>)}</ul> : <p className="mt-2 text-sm text-slate-400">No hay pagos asociados.</p>}</div></div><button type="button" onClick={onClose} className="button-secondary mt-5">Cerrar detalle</button></Panel>; }

function receptionFor(state: State, order: Order): State['receptions'][number] { return state.receptions.find((x) => x.orderId === order.id) || { id: `REC-${order.id}`, orderId: order.id, createdAt: today, lines: order.lines.map((line) => ({ id: `rl-${line.id}`, orderLineId: line.id, status: 'pending' as ReceptionStatus, expected: line.quantity, received: 0, expiry: '', lot: '', note: '', controlExpiry: false })) }; }
function Reception({ state, update, notify, userName }: { state: State; update: Mutate; notify: (m: string) => void; userName: string }) {
  const pendingOrders = useMemo(() => state.orders.filter((o) => isOrderOpen(o)), [state.orders]); const supplierIds = Array.from(new Set(pendingOrders.map((o) => o.supplierId)));
  const [requestedOrderId] = useState(() => { try { const id = window.sessionStorage.getItem('zavryon-receive-order'); window.sessionStorage.removeItem('zavryon-receive-order'); return id; } catch { return null; } });
  const requestedOrder = pendingOrders.find((o) => o.id === requestedOrderId);
  const [supplierId, setSupplierId] = useState(requestedOrder?.supplierId || supplierIds[0] || state.suppliers[0]?.id || ''); const supplierOrders = pendingOrders.filter((o) => o.supplierId === supplierId); const [orderId, setOrderId] = useState(requestedOrder?.id || supplierOrders[0]?.id || ''); const order = state.orders.find((x) => x.id === orderId && isOrderOpen(x)) || supplierOrders[0]; const [draft, setDraft] = useState(order ? receptionFor(state, order) : null); const activeUsers = useMemo(() => state.users.filter((u) => u.active), [state.users]); const [responsible, setResponsible] = useState(userName); const [draftInfo, setDraftInfo] = useState<{ savedAt: string | null; error?: string; recovered?: boolean }>({ savedAt: null });
  const stateRef = useRef(state); stateRef.current = state;
  useEffect(() => { if (!pendingOrders.some((o) => o.supplierId === supplierId) && pendingOrders[0]) setSupplierId(pendingOrders[0].supplierId); }, [supplierId, pendingOrders]);
  useEffect(() => { const next = pendingOrders.filter((o) => o.supplierId === supplierId); if (!next.some((o) => o.id === orderId)) setOrderId(next[0]?.id || ''); }, [supplierId, orderId, pendingOrders]);
  // Reset the working copy only when the selected order changes, never on unrelated state updates (alerts, stock…), so typed values are not lost.
  const orderKey = order?.id;
  useEffect(() => { const current = stateRef.current; const selected = current.orders.find((o) => o.id === orderKey); if (!selected) { setDraft(null); return; } setDraft(receptionFor(current, selected)); setResponsible(current.receptions.find((r) => r.orderId === selected.id)?.responsible || userName); const recovered = loadDraft<{ supplierId: string; orderId: string; draft: State['receptions'][number]; responsible: string }>(`receiving:${selected.id}`); if (recovered && recovered.data.orderId === selected.id) { setDraft(recovered.data.draft); setResponsible(recovered.data.responsible); setDraftInfo({ savedAt: recovered.savedAt, recovered: recovered.recovered }); } else setDraftInfo({ savedAt: null }); }, [orderKey, userName]);
  useEffect(() => { if (!orderKey || !draft) return; const timer = window.setTimeout(() => { const result = saveDraft(`receiving:${orderKey}`, { supplierId, orderId: orderKey, draft, responsible }); setDraftInfo({ savedAt: result.savedAt, error: result.error }); if (result.error) notify(`Error de guardado: ${result.error}`); }, 350); return () => window.clearTimeout(timer); }, [orderKey, supplierId, draft, responsible, notify]);
  const save = (complete: boolean) => {
    if (!draft || !order) return;
    if (complete && draft.lines.some((line) => line.status === 'pending')) return notify('Resolvé cada línea (llegó, faltante, etc.) antes de completar la recepción');
    if (draft.lines.some((line) => line.controlExpiry && line.received > 0 && (!line.expiry || !line.lot.trim()))) return notify('Completá lote y fecha en las líneas con control de vencimiento');
    const now = new Date().toISOString(); const arrivedAt = complete ? (draft.arrivedAt || now) : draft.arrivedAt;
    let stockChanges = 0;
    update((current) => {
      const previous = current.receptions.find((r) => r.orderId === order.id);
      const currentOrder = current.orders.find((o) => o.id === order.id) || order;
      let saved: State["receptions"][number] = { ...draft, responsible, arrivedAt };
      let products = current.products; let stockMovements = current.stockMovements;
      if (complete) { const applied = applyReceptionToStock(current.products, currentOrder, saved, previous, { user: responsible || userName, date: now }); saved = applied.reception; products = applied.products; stockMovements = [...current.stockMovements, ...applied.movements].slice(-2000); stockChanges = applied.movements.length; }
      const receptions = [...current.receptions.filter((r) => r.orderId !== order.id), saved];
      const expiries = saved.lines.filter((line) => line.controlExpiry && line.expiry && line.lot).map((line) => { const ol = currentOrder.lines.find((x) => x.id === line.orderLineId); return ol ? { id: `${saved.id}-${line.id}`, supplierId: currentOrder.supplierId, productId: ol.productId, lot: line.lot, quantity: line.received, date: line.expiry, receptionId: saved.id } : null; }).filter((x): x is Expiry => Boolean(x));
      const differences = saved.lines.some((line) => line.status !== 'received');
      const nextStatus = complete ? 'Recibido' as const : orderStage(currentOrder.status) === 'en-recepcion' ? null : 'En recepción' as const;
      return { ...current, products, stockMovements, receptions, expiries: [...current.expiries.filter((e) => e.receptionId !== saved.id), ...expiries], orders: nextStatus ? current.orders.map((o) => o.id === order.id ? withStatus(o, nextStatus, responsible || userName, complete && differences ? 'Recibido con diferencias' : undefined, now) : o) : current.orders };
    });
    if (complete) { discardDraft(`receiving:${order.id}`); setDraftInfo({ savedAt: null }); }
    notify(complete ? `Recepción de ${order.id} completa${stockChanges ? ` · stock actualizado en ${stockChanges} producto(s)` : ''}` : 'Avance de recepción guardado');
  };
  const setLine = (lineId: string, patch: Partial<ReceptionLine>) => setDraft((current) => current ? { ...current, lines: current.lines.map((line) => line.id === lineId ? { ...line, ...patch } : line) } : current);
  const markAllReceived = () => setDraft((current) => current ? { ...current, lines: current.lines.map((line) => line.status === 'pending' ? { ...line, status: 'received', received: line.expected } : line) } : current);
  if (!pendingOrders.length) return <Panel title="Recepción" subtitle="Entrada de mercadería"><EmptyState text="No hay pedidos pendientes por recibir. Confirmá un pedido para recibirlo cuando llegue." /></Panel>;
  return <><Panel title="Recepción por proveedor" subtitle="Elegí el proveedor que llegó y el pedido a controlar"><div className="grid gap-4 lg:grid-cols-2"><Field label="Proveedor con pedidos por recibir"><select className="field w-full" value={supplierId} onChange={(e) => { setSupplierId(e.target.value); setOrderId(''); }}>{supplierIds.map((id) => <option key={id} value={id}>{supplierName(state.suppliers, id)} · {pendingOrders.filter((o) => o.supplierId === id).length} pedido(s)</option>)}</select></Field><Field label="Pedido"><select className="field w-full" value={order?.id || ''} onChange={(e) => setOrderId(e.target.value)}>{supplierOrders.map((o) => <option key={o.id} value={o.id}>{o.id} · {stageLabels[orderStage(o.status)]} · {dateEs(o.expectedDate)} · {money(orderTotal(o))}</option>)}</select></Field></div><div className="mt-4 grid gap-3 sm:grid-cols-3">{supplierIds.map((id) => { const orders = pendingOrders.filter((o) => o.supplierId === id); return <button type="button" key={id} onClick={() => { setSupplierId(id); setOrderId(orders[0]?.id || ''); }} className={`rounded-xl border p-3 text-left transition ${id === supplierId ? 'border-cyan-300/50 bg-cyan-400/10' : 'border-white/10 hover:border-white/25'}`}><div className="font-bold text-white">{supplierName(state.suppliers, id)}</div><div className="mt-1 text-xs text-slate-400">{orders.length} pedido(s) · {money(orders.reduce((sum, o) => sum + orderTotal(o), 0))}</div></button>; })}</div></Panel>
  {order && draft && <div className="mt-6"><Panel title={`Líneas de ${order.id}`} subtitle={`${supplierName(state.suppliers, order.supplierId)} · ${draftInfo.error ? `Error de guardado: ${draftInfo.error}` : draftInfo.savedAt ? `Borrador guardado ${new Date(draftInfo.savedAt).toLocaleTimeString('es-AR', { timeStyle: 'short' })}${draftInfo.recovered ? ' (recuperado)' : ''}` : 'cada cambio se guarda como borrador'}`} action={<div className="flex flex-wrap items-end gap-2"><Field label="Responsable"><select className="field" value={responsible} onChange={(e) => setResponsible(e.target.value)}>{activeUsers.map((u) => <option key={u.id}>{u.name}</option>)}{!activeUsers.some((u) => u.name === responsible) && responsible && <option>{responsible}</option>}</select></Field><button type="button" className="button-secondary" onClick={markAllReceived}><CheckCircleIcon className="h-4 w-4" /> Todo llegó completo</button></div>}><div className="space-y-4">{draft.lines.map((line) => { const ol = order.lines.find((x) => x.id === line.orderLineId); const product = state.products.find((p) => p.id === ol?.productId); const diff = line.received - line.expected; return <div key={line.id} className="rounded-xl border border-white/10 p-4"><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><div><div className="font-bold text-white">{product?.name || 'Producto eliminado'}</div><div className="text-xs text-slate-400">Esperada: {line.expected} · Recibida: {line.received} · Diferencia: <span className={diff < 0 ? 'text-red-300' : diff > 0 ? 'text-amber-300' : 'text-emerald-300'}>{diff > 0 ? `+${diff}` : diff}</span>{product ? ` · stock actual ${product.stock}` : ''}</div></div><Badge value={receptionLabels[line.status]} /></div><div className="grid gap-3 sm:grid-cols-2 md:grid-cols-5"><Field label="Estado"><select className="field w-full" value={line.status} onChange={(e) => { const status = e.target.value as ReceptionStatus; setLine(line.id, { status, ...(status === 'received' && line.received === 0 ? { received: line.expected } : {}) }); }}>{Object.entries(receptionLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></Field><Field label="Cantidad recibida"><input className="field w-full" type="number" inputMode="numeric" min="0" value={line.received} onChange={(e) => setLine(line.id, { received: toNumber(e.target.value) })} /></Field><Field label="Lote"><input className="field w-full" value={line.lot} onChange={(e) => setLine(line.id, { lot: e.target.value })} /></Field><Field label="Nota"><input className="field w-full" value={line.note} onChange={(e) => setLine(line.id, { note: e.target.value })} /></Field><Field label="Controlar vencimiento"><label className="flex min-h-10 items-center gap-2 rounded-lg border border-white/15 bg-[#0c2330] px-3 text-xs"><input type="checkbox" className="h-4 w-4 accent-cyan-400" checked={Boolean(line.controlExpiry)} onChange={(e) => setLine(line.id, { controlExpiry: e.target.checked })} /> Sí</label></Field></div>{line.controlExpiry && <div className="mt-3 max-w-xs"><Field label="Fecha de vencimiento"><input className="field w-full" type="date" value={line.expiry} onChange={(e) => setLine(line.id, { expiry: e.target.value })} /></Field></div>}</div>; })}</div><div className="mt-5 flex flex-wrap items-center gap-2 border-t border-white/10 pt-4"><button type="button" className="button-primary" onClick={() => save(true)}><CheckCircleIcon className="h-4 w-4" /> Completar recepción y sumar al stock</button><button type="button" className="button-secondary" onClick={() => save(false)}>Guardar avance</button><span className="text-xs text-slate-400">Llegada: {draft.arrivedAt ? new Date(draft.arrivedAt).toLocaleString('es-AR', { dateStyle: 'short', timeStyle: 'short' }) : 'aún no registrada'}</span></div></Panel></div>}</>;
}
function Arrivals({ state, onNavigate }: { state: State; onNavigate: (s: Section) => void }) { const rows = state.receptions.map((r) => ({ r, order: state.orders.find((o) => o.id === r.orderId) })).filter((x) => x.order); return <Panel title="Proveedores llegados" subtitle="Recepciones por fecha, hora, pedido, estado y diferencias">{rows.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Fecha / hora</th><th>Proveedor</th><th>Pedido</th><th>Estado</th><th>Recibido</th><th>Diferencias</th><th /></tr></thead><tbody>{rows.map(({ r, order }) => { const received = r.lines.reduce((sum, l) => sum + l.received, 0); const differences = r.lines.filter((l) => l.status !== 'received').length; return <tr key={r.id}><td>{r.arrivedAt ? `${dateEs(r.arrivedAt)} · ${r.arrivedAt.slice(11, 16)}` : `${dateEs(r.createdAt)} · Pendiente`}</td><td className="font-semibold text-white">{supplierName(state.suppliers, order!.supplierId)}</td><td>{order!.id}</td><td><Badge value={r.arrivedAt ? 'Llegó' : 'Pendiente'} /></td><td>{received} uds.</td><td>{differences ? <Badge value={`${differences} diferencia(s)`} /> : 'Sin diferencias'}</td><td><button type="button" onClick={() => onNavigate('Recepcion')} className="button-secondary">Abrir</button></td></tr>; })}</tbody></table></div> : <EmptyState text="Todavía no hay recepciones guardadas." />}</Panel>; }
function Suppliers({ state, update, notify }: { state: State; update: Mutate; notify: (m: string) => void }) {
  const [query, setQuery] = useState('');
  const [editing, setEditing] = useState<Supplier | null>(null);
  const paymentOptions = paymentPreferences;
  const filtered = state.suppliers.filter((x) => `${x.name} ${x.contact} ${x.active ? 'activo' : 'inactivo'}`.toLowerCase().includes(query.toLowerCase()));
  const printSupplier = useCallback((supplier: Supplier) => { if (!printSupplierWindow(state.config, supplier)) notify('Permite ventanas emergentes para imprimir el proveedor'); }, [state.config, notify]);
  const add = () => setEditing({ id: `sup-${Date.now()}`, name: '', contact: '', phone: '', email: '', address: '', terms: 'Efectivo', notes: '', active: true });
  const isNew = Boolean(editing && !state.suppliers.some((item) => item.id === editing.id));
  const open = (supplier: Supplier) => setEditing({ ...supplier, terms: normalizePaymentPreference(supplier.terms) });
  const save = () => {
    if (!editing?.name.trim()) return notify('El nombre del proveedor es obligatorio');
    if (editing.email && !EMAIL_PATTERN.test(editing.email.trim())) return notify('Ingresá un email válido');
    if (state.suppliers.some((item) => item.id !== editing.id && item.name.trim().toLowerCase() === editing.name.trim().toLowerCase())) return notify('Ya existe un proveedor con ese nombre');
    if (!editing.terms.trim()) return notify('Selecciona o escribe una preferencia de pago');
    const saved = { ...editing, name: editing.name.trim(), contact: editing.contact.trim(), phone: editing.phone.trim(), email: editing.email.trim(), address: editing.address.trim(), terms: editing.terms.trim() };
    update((current) => ({ ...current, suppliers: current.suppliers.some((item) => item.id === saved.id) ? current.suppliers.map((item) => item.id === saved.id ? saved : item) : [...current.suppliers, saved] }));
    setEditing(null);
    notify(isNew ? 'Proveedor creado' : 'Proveedor actualizado');
  };
  const remove = (supplier: Supplier) => { const dependencies = [state.orders.some((x) => x.supplierId === supplier.id) && 'pedidos', state.receptions.some((x) => state.orders.some((order) => order.id === x.orderId && order.supplierId === supplier.id)) && 'recepciones', state.payments.some((x) => x.supplierId === supplier.id) && 'pagos', state.sources.some((x) => x.supplierId === supplier.id) && 'fuentes', state.supplierProducts.some((x) => x.supplierId === supplier.id) && 'relaciones de catálogo'].filter(Boolean) as string[]; if (dependencies.length) { if (window.confirm(`No se puede eliminar ${supplier.name} porque conserva ${dependencies.join(', ')}. ¿Desactivar proveedor?`)) { update((current) => ({ ...current, suppliers: current.suppliers.map((item) => item.id === supplier.id ? { ...item, active: false } : item) })); notify('Proveedor desactivado; su historial se conserva y no aparecerá en nuevos pedidos.'); } return; } if (window.confirm(`¿Eliminar definitivamente a ${supplier.name}? Esta acción elimina el dato demo sin historial asociado.`)) { update((current) => ({ ...current, suppliers: current.suppliers.filter((item) => item.id !== supplier.id), supplierProducts: current.supplierProducts.filter((item) => item.supplierId !== supplier.id) })); notify('Proveedor eliminado'); } };
  return <><Panel title="Proveedores" subtitle="Directorio y saldo de pagos; los proveedores con historial se desactivan para conservar trazabilidad." action={<div className="flex flex-wrap gap-2"><input aria-label="Buscar proveedores" className="field w-full sm:w-48" placeholder="Buscar..." value={query} onChange={(e) => setQuery(e.target.value)} /><button type="button" onClick={add} className="button-primary"><PlusIcon className="h-4 w-4" /> Nuevo</button></div>}><div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Proveedor</th><th>Contacto</th><th>Preferencia de pago</th><th>Estado</th><th>Pagado</th><th>Pendiente</th><th>Acción</th></tr></thead><tbody>{filtered.map((s) => { const paid = state.payments.filter((p) => p.supplierId === s.id && !p.cancelled && p.status === 'pagado').reduce((a, p) => a + p.amount, 0); const due = state.payments.filter((p) => p.supplierId === s.id && !p.cancelled && p.status !== 'pagado').reduce((a, p) => a + p.amount, 0); return <tr key={s.id}><td className="font-bold text-white">{s.name}</td><td>{s.contact || 'Sin contacto'}{s.phone && <div className="text-xs"><a className="text-cyan-300 hover:underline" href={`tel:${s.phone.replace(/[^+\d]/g, '')}`}>{s.phone}</a></div>}</td><td>{s.terms || 'Sin definir'}</td><td><Badge value={s.active ? 'Activo' : 'Desactivado'} /></td><td className="text-emerald-300">{money(paid)}</td><td className="text-amber-300">{money(due)}</td><td><div className="flex flex-wrap gap-2"><button type="button" className="button-secondary" onClick={() => open(s)}>Editar</button><button type="button" className="button-danger" onClick={() => remove(s)}>{s.active ? 'Eliminar' : 'Eliminar / revisar'}</button></div></td></tr>; })}</tbody></table></div></Panel>{editing && <Panel title={isNew ? 'Nuevo proveedor' : `Editar proveedor: ${editing.name}`} subtitle="Los cambios se guardan solo al confirmar. Cancelar descarta este borrador."><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><Field label="Nombre *"><input className="field w-full" autoFocus value={editing.name} onChange={(e) => setEditing({ ...editing, name: e.target.value })} /></Field><Field label="Contacto"><input className="field w-full" value={editing.contact} onChange={(e) => setEditing({ ...editing, contact: e.target.value })} /></Field><Field label="Teléfono"><input className="field w-full" type="tel" value={editing.phone} onChange={(e) => setEditing({ ...editing, phone: e.target.value })} /></Field><Field label="Email"><input className="field w-full" type="email" value={editing.email} onChange={(e) => setEditing({ ...editing, email: e.target.value })} /></Field><Field label="Dirección"><input className="field w-full" value={editing.address} onChange={(e) => setEditing({ ...editing, address: e.target.value })} /></Field><Field label="Preferencia de pago"><select className="field w-full" value={paymentOptions.includes(editing.terms) ? editing.terms : 'Otro'} onChange={(e) => setEditing({ ...editing, terms: e.target.value === 'Otro' ? '' : e.target.value })}><option value="">Selecciona una opción</option>{paymentOptions.map((option) => <option key={option} value={option}>{option}</option>)}</select></Field>{(!paymentOptions.includes(editing.terms) || editing.terms === '') && <Field label="Otra preferencia *"><input className="field w-full" value={editing.terms} placeholder="Ej. 30 días" onChange={(e) => setEditing({ ...editing, terms: e.target.value })} /></Field>}<Field label="Notas"><textarea className="field min-h-24 w-full" value={editing.notes} onChange={(e) => setEditing({ ...editing, notes: e.target.value })} /></Field></div><div className="mt-5 flex flex-wrap justify-end gap-2"><button type="button" className="button-secondary" onClick={() => setEditing(null)}>Cancelar</button><button type="button" className="button-primary" onClick={save}>Guardar cambios</button></div></Panel>}</>;
}

function Catalog({ state, update, notify }: { state: State; update: Mutate; notify: (m: string) => void }) { const [query, setQuery] = useState(''); const [editing, setEditing] = useState<Product | null>(null); const [supplierId, setSupplierId] = useState(state.suppliers[0]?.id || ''); const [price, setPrice] = useState(0); const filtered = state.products.filter((p) => `${p.name} ${p.sku} ${p.category} ${p.brand || ''}`.toLowerCase().includes(query.toLowerCase())); const open = (product: Product) => { setEditing({ ...product }); const link = state.supplierProducts.find((x) => x.productId === product.id); setSupplierId(link?.supplierId || state.suppliers[0]?.id || ''); setPrice(link?.price || 0); }; const categories = Array.from(new Set(state.products.map((p) => p.category.trim()).filter(Boolean))).sort((a, b) => a.localeCompare(b, 'es')); const save = () => { if (!editing?.name.trim() || !editing.sku.trim()) return notify('Completá nombre y SKU'); if (state.products.some((p) => p.id !== editing.id && p.sku.trim().toLowerCase() === editing.sku.trim().toLowerCase())) return notify(`El SKU ${editing.sku} ya está en uso`); editing.name = editing.name.trim(); editing.sku = editing.sku.trim(); editing.category = editing.category.trim(); const link: SupplierProduct = { id: state.supplierProducts.find((x) => x.productId === editing.id && x.supplierId === supplierId)?.id || `sp-${Date.now()}`, supplierId, productId: editing.id, price, externalCode: editing.sku, presentation: editing.unit, active: editing.active }; update((current) => ({ ...current, products: current.products.some((x) => x.id === editing.id) ? current.products.map((x) => x.id === editing.id ? editing : x) : [...current.products, editing], supplierProducts: supplierId ? [...current.supplierProducts.filter((x) => !(x.productId === editing.id && x.supplierId === supplierId)), link] : current.supplierProducts })); setEditing(null); notify('Producto guardado'); }; const newProduct = () => { setEditing({ id: `prod-${Date.now()}`, name: '', sku: generateInternalSku(state.products), category: '', unit: '', stock: 0, minimum: 0, active: true }); setSupplierId(state.suppliers[0]?.id || ''); setPrice(0); }; return <><Panel title="Catálogo" subtitle="Productos, marcas, presentaciones, precios y procedencia" action={<div className="flex flex-wrap gap-2"><input aria-label="Buscar productos" className="field w-full sm:w-52" placeholder="Buscar nombre, SKU..." value={query} onChange={(e) => setQuery(e.target.value)} /><button type="button" onClick={newProduct} className="button-primary"><PlusIcon className="h-4 w-4" /> Nuevo producto</button></div>}>{filtered.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Producto / SKU</th><th>Marca / categoría</th><th>Presentación</th><th>Stock</th><th>Proveedor</th><th>Precio</th><th>Estado</th><th /></tr></thead><tbody>{filtered.map((p) => { const link = state.supplierProducts.find((x) => x.productId === p.id); return <tr key={p.id}><td className="font-bold text-white"><div className="flex items-center gap-3">{p.imageUrl ? <img src={p.imageUrl} alt="" loading="lazy" referrerPolicy="no-referrer" className="h-10 w-10 shrink-0 rounded-md bg-white/5 object-contain" /> : null}<div>{p.name}<div className="text-xs font-normal text-slate-500">{p.sku}</div></div></div></td><td>{p.brand || 'Sin marca'}<div className="text-xs">{p.category || 'Sin categoría'}</div></td><td>{p.unit || 'Sin presentación'}</td><td className="whitespace-nowrap">{p.stock} / mín. {p.minimum}<div className="mt-1"><Badge value={stockStatus(p) === 'ok' ? 'OK' : stockStatus(p) === 'faltante' ? 'Faltante' : stockStatus(p) === 'poco' ? 'Poco' : 'Bajo'} /></div></td><td>{link ? supplierName(state.suppliers, link.supplierId) : 'Sin proveedor'}</td><td>{link ? money(link.price) : '—'}</td><td><Badge value={p.active ? 'Activo' : 'Inactivo'} /></td><td><button type="button" className="button-secondary" onClick={() => open(p)}>Detalle / editar</button></td></tr>; })}</tbody></table></div> : <EmptyState text="No hay productos que coincidan." />}</Panel>{editing && <Panel title={state.products.some((x) => x.id === editing.id) ? 'Editar producto' : 'Alta de producto'} subtitle="Los cambios se conservan en este navegador"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Field label="Nombre"><input className="field w-full" value={editing.name} onChange={(e) => setEditing({ ...editing, name: e.target.value })} /></Field><Field label="SKU"><input className="field w-full" value={editing.sku} onChange={(e) => setEditing({ ...editing, sku: e.target.value })} /></Field><Field label="Marca"><input className="field w-full" value={editing.brand || ''} onChange={(e) => setEditing({ ...editing, brand: e.target.value })} /></Field><Field label="Categoría"><input className="field w-full" list="catalog-categories" value={editing.category} onChange={(e) => setEditing({ ...editing, category: e.target.value })} /><datalist id="catalog-categories">{categories.map((c) => <option key={c} value={c} />)}</datalist></Field><Field label="Presentación / unidad"><input className="field w-full" value={editing.unit} onChange={(e) => setEditing({ ...editing, unit: e.target.value })} /></Field><Field label="Stock"><input className="field w-full" type="number" min="0" value={editing.stock} onChange={(e) => setEditing({ ...editing, stock: toNumber(e.target.value) })} /></Field><Field label="Mínimo"><input className="field w-full" type="number" min="0" value={editing.minimum} onChange={(e) => setEditing({ ...editing, minimum: toNumber(e.target.value) })} /></Field><Field label="Proveedor"><select className="field w-full" value={supplierId} onChange={(e) => setSupplierId(e.target.value)}>{state.suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="Precio"><input className="field w-full" type="number" min="0" value={price} onChange={(e) => setPrice(toNumber(e.target.value))} /></Field><Field label="Estado"><label className="flex min-h-10 items-center gap-2 rounded-lg border border-white/15 bg-[#0c2330] px-3 text-xs"><input type="checkbox" className="h-4 w-4 accent-cyan-400" checked={editing.active} onChange={(e) => setEditing({ ...editing, active: e.target.checked })} /> Activo</label></Field></div><div className="mt-5 flex gap-2"><button type="button" className="button-primary" onClick={save}>Guardar producto</button><button type="button" className="button-secondary" onClick={() => setEditing(null)}>Cancelar</button></div></Panel>}</>; }

function safeSourceUrl(value: string) { try { assertSafeUrl(value); return true; } catch { return false; } }
function Sources({ state, update, notify }: { state: State; update: Mutate; notify: (m: string) => void }) {
  const [supplierId, setSupplierId] = useState(state.suppliers[0]?.id || ''); const [kind, setKind] = useState<'PDF' | 'URL'>('URL'); const [name, setName] = useState(''); const [url, setUrl] = useState(''); const [file, setFile] = useState<File | null>(null); const [files, setFiles] = useState<Record<string, File>>({}); const [selected, setSelected] = useState<string | null>(state.sources[0]?.id || null); const source = state.sources.find((s) => s.id === selected); const statuses: ReviewStatus[] = ['Pendiente', 'Revisado', 'Confirmado', 'Rechazado']; const maxPdf = 5 * 1024 * 1024; const [draftInfo, setDraftInfo] = useState<{ savedAt: string | null; error?: string; recovered?: boolean }>({ savedAt: null });
  useEffect(() => { const recovered = loadDraft<{ supplierId: string; kind: 'PDF' | 'URL'; name: string; url: string; selected: string | null }>('sources-review'); if (recovered) { setSupplierId(recovered.data.supplierId); setKind(recovered.data.kind); setName(recovered.data.name); setUrl(recovered.data.url); setSelected(recovered.data.selected); setDraftInfo({ savedAt: recovered.savedAt, recovered: recovered.recovered }); } }, []);
  useEffect(() => { const timer = window.setTimeout(() => { const result = saveDraft('sources-review', { supplierId, kind, name, url, selected }, file ? { name: file.name, size: file.size, type: file.type, lastModified: file.lastModified } : undefined); setDraftInfo({ savedAt: result.savedAt, error: result.error }); if (result.error) notify(`Error de guardado: ${result.error}`); }, 350); return () => window.clearTimeout(timer); }, [supplierId, kind, name, url, selected, file, notify]);
  const add = () => { if (!supplierId || !name.trim() || (kind === 'URL' && !url.trim()) || (kind === 'PDF' && !file)) return notify('Completa proveedor, nombre y la fuente'); if (kind === 'URL' && !safeSourceUrl(url)) return notify('La URL debe ser pública y comenzar con http:// o https://'); if (kind === 'PDF' && file && (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf'))) return notify('Solo se permiten archivos PDF'); if (kind === 'PDF' && file && file.size > maxPdf) return notify('El PDF supera el máximo de 5 MB'); const newSource: Source = { id: `src-${Date.now()}`, supplierId, kind, name: name.trim(), url: kind === 'URL' ? url.trim() : undefined, fileName: file?.name, size: file?.size, contentType: file?.type, date: today, status: 'Pendiente', notes: '', provenance: kind === 'URL' ? `URL pública declarada: ${url.trim()}` : `Archivo local subido: ${file?.name}`, extractionStatus: 'Pendiente', candidates: [] }; update((current) => ({ ...current, sources: [...current.sources, newSource] })); if (file) setFiles((current) => ({ ...current, [newSource.id]: file })); setSelected(newSource.id); setName(''); setUrl(''); setFile(null); if (file) void review(newSource, file); notify('Fuente registrada; inicia la revisión para extraer candidatos'); };
  const review = async (item: Source, fileOverride?: File) => { const pdfFile = fileOverride || files[item.id]; update((current) => ({ ...current, sources: current.sources.map((s) => s.id === item.id ? { ...s, extractionStatus: 'Pendiente', extractionError: undefined } : s) })); try { let text = ''; let remote: { pdfBase64?: string; contentType?: string; finalUrl?: string } = {}; if (item.kind === 'PDF') { notify('Leyendo capa de texto del PDF; no es OCR'); if (!pdfFile) throw new Error('El archivo PDF no queda disponible tras recargar; vuelva a subirlo para revisar.'); } else { const response = await fetch('/api/source-preview', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ url: item.url }) }); const payload = await response.json() as { text?: string | null; error?: string; pdfBase64?: string; contentType?: string; finalUrl?: string }; if (!response.ok) throw new Error(payload.error || 'No se pudo leer la URL'); text = payload.text || ''; remote = payload; } const extraction = item.kind === 'PDF' ? await extractPdf(pdfFile!, item.id) : remote.pdfBase64 ? await extractPdf(Uint8Array.from(atob(remote.pdfBase64), (char) => char.charCodeAt(0)), item.id) : remote.contentType?.includes('json') ? extractJson(text, item.id) : remote.contentType === 'text/csv' ? extractText(csvToText(text), item.id) : remote.contentType === 'text/plain' ? extractText(text, item.id) : extractHtml(text, item.id, remote.finalUrl || item.url); const candidates = extraction.candidates; update((current) => ({ ...current, sources: current.sources.map((s) => s.id === item.id ? { ...s, extractionStatus: extraction.status === 'ok' ? 'Extraído' : 'Revisión manual', extractedAt: new Date().toISOString(), candidates, notes: extraction.warnings.join(' ') || 'Candidatos detectados, pendientes de edición y confirmación.' } : s) })); notify(candidates.length ? `${candidates.length} candidato(s) detectado(s)` : extraction.warnings[0] || 'No se detectaron candidatos; la revisión manual queda habilitada'); } catch (error) { const message = error instanceof Error ? error.message : 'Error desconocido'; update((current) => ({ ...current, sources: current.sources.map((s) => s.id === item.id ? { ...s, extractionStatus: 'Error', extractionError: message } : s) })); notify(`No se pudo extraer: ${message}`); } };
  const editCandidate = (candidate: SourceCandidate, patch: Partial<SourceCandidate>) => source && update((current) => ({ ...current, sources: current.sources.map((s) => s.id === source.id ? { ...s, candidates: s.candidates.map((c) => { if (c.id !== candidate.id) return c; const edited = applyCandidatePatch(c, patch); if (patch.status === 'Aprobado') return approveCandidate(edited) || { ...edited, status: 'Pendiente', reviewState: 'needs_review' }; return edited; }) } : s) }));
  const addCandidate = () => source && update((current) => ({ ...current, sources: current.sources.map((s) => s.id === source.id ? { ...s, candidates: [...s.candidates, normalizeSourceCandidate({ id: `${s.id}-manual-${Date.now()}`, name: '', sku: '', brand: '', unit: '', category: '', price: 0, currency: 'ARS', availability: '', expiry: '', imageUrl: '', status: 'Pendiente', notes: 'Agregado manualmente' })] } : s) }));
  /** Pure import step, used both to preview the counts and inside the state update. */
  const importApproved = (current: State, sourceId: string) => {
    let products = [...current.products]; let supplierProducts = [...current.supplierProducts]; let created = 0; let updated = 0;
    const currentSource = current.sources.find((item) => item.id === sourceId);
    if (!currentSource) return { next: current, created, updated };
    const currentApproved = currentSource.candidates.filter(canImportCandidate);
    currentApproved.forEach((c) => {
      const supplierCode = c.sku.trim();
      // Match an existing product by this supplier's own code first, then by name; never by another supplier's code.
      const byCode = supplierCode ? supplierProducts.find((link) => link.supplierId === currentSource.supplierId && (link.externalCode || '').toLowerCase() === supplierCode.toLowerCase()) : undefined;
      const existing = (byCode && products.find((p) => p.id === byCode.productId)) || products.find((p) => p.name.trim().toLowerCase() === c.name.trim().toLowerCase());
      const product: Product = existing
        ? { ...existing, name: c.name.trim(), brand: c.brand || existing.brand, unit: c.unit || existing.unit, category: c.category || existing.category, currency: c.currency, availability: c.availability || existing.availability, imageUrl: c.imageUrl || existing.imageUrl, sourceId: currentSource.id }
        : { id: `prod-${Date.now()}-${created}`, name: c.name.trim(), sku: generateInternalSku(products), brand: c.brand, unit: c.unit, category: c.category, stock: 0, minimum: 0, active: true, currency: c.currency, availability: c.availability, expiry: c.expiry, imageUrl: c.imageUrl || undefined, sourceId: currentSource.id };
      if (existing) { products = products.map((p) => p.id === existing.id ? product : p); updated += 1; } else { products.push(product); created += 1; }
      const previousLink = supplierProducts.find((x) => x.productId === product.id && x.supplierId === currentSource.supplierId);
      supplierProducts = [...supplierProducts.filter((x) => !(x.productId === product.id && x.supplierId === currentSource.supplierId)), { id: previousLink?.id || `sp-${currentSource.id}-${c.id}`, supplierId: currentSource.supplierId, productId: product.id, price: c.price, currency: c.currency, externalCode: supplierCode || previousLink?.externalCode, brand: c.brand || previousLink?.brand, category: c.category || previousLink?.category, presentation: c.unit || previousLink?.presentation, availability: c.availability || previousLink?.availability, active: true }];
    });
    const importedIds = new Set(currentApproved.map((c) => c.id));
    const stamp = new Date().toLocaleDateString('es-AR');
    const next = currentApproved.length ? { ...current, products, supplierProducts, sources: current.sources.map((s) => s.id === currentSource.id ? { ...s, status: 'Confirmado' as const, candidates: s.candidates.map((c) => importedIds.has(c.id) ? { ...c, notes: `${c.notes.replace(/ · Importado.*$/, '')} · Importado ${stamp}` } : c) } : s) } : current;
    return { next, created, updated };
  };
  const confirmCandidates = () => {
    if (!source) return;
    const preview = importApproved(state, source.id);
    if (!preview.created && !preview.updated) return notify('Revisá los candidatos y marcá como Aprobado al menos uno con nombre y precio');
    update((current) => importApproved(current, source.id).next);
    notify(`${preview.created} producto(s) nuevo(s) con código interno y ${preview.updated} actualizado(s). Precios cargados para ${supplierName(state.suppliers, source.supplierId)}.`);
  };
  const approveAll = () => {
    if (!source) return;
    const approvable = (c: SourceCandidate) => c.status === 'Pendiente' && Boolean(c.name.trim()) && c.price > 0 && Boolean(approveCandidate(applyCandidatePatch(c, { status: 'Aprobado' })));
    const count = source.candidates.filter(approvable).length;
    if (!count) return notify('No hay candidatos pendientes con nombre, precio y evidencia para aprobar');
    update((current) => ({ ...current, sources: current.sources.map((s) => s.id === source.id ? { ...s, candidates: s.candidates.map((c) => approvable(c) ? approveCandidate(applyCandidatePatch(c, { status: 'Aprobado' })) || c : c) } : s) }));
    notify(`${count} candidato(s) aprobados. Revisalos y tocá “Importar aprobados”.`);
  };

  const remove = (id: string) => { if (!window.confirm('¿Eliminar esta fuente?')) return; update((current) => ({ ...current, sources: current.sources.filter((s) => s.id !== id) })); if (selected === id) setSelected(null); notify('Fuente eliminada'); };
  return <><Panel title="Fuentes de catálogos" subtitle="Asocia PDF o URL a un proveedor. La extracción siempre requiere revisión humana."><div className="grid gap-3 md:grid-cols-5"><Field label="Proveedor"><select className="field w-full" value={supplierId} onChange={(e) => setSupplierId(e.target.value)}>{state.suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="Tipo"><select className="field w-full" value={kind} onChange={(e) => setKind(e.target.value as 'PDF' | 'URL')}><option value="URL">URL pública</option><option value="PDF">PDF</option></select></Field><Field label="Nombre"><input className="field w-full" value={name} onChange={(e) => setName(e.target.value)} placeholder="Catálogo septiembre" /></Field>{kind === 'URL' ? <Field label="URL"><input className="field w-full" type="url" value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://..." /></Field> : <Field label="Archivo PDF"><input className="field w-full" type="file" accept="application/pdf,.pdf" onChange={(e) => setFile(e.target.files?.[0] || null)} /><span className="mt-1 block text-[10px] text-slate-500">Máximo 5 MB. No OCR productivo.</span></Field>}<div className="flex items-end"><button type="button" className="button-primary w-full" onClick={add}>Registrar fuente</button></div></div><p className="mt-4 text-xs text-slate-500">Las URL se leen solo vía servidor con http/https público; se bloquean localhost, IPs privadas, file://, javascript: y cuerpos mayores a 5 MB.</p></Panel><Panel title="Cola de revisión" subtitle={`${state.sources.length} fuente(s) · procedencia, metadata y estado persistidos`}>{state.sources.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Fuente / procedencia</th><th>Proveedor</th><th>Tipo / tamaño</th><th>Extracción</th><th>Revisión</th><th /></tr></thead><tbody>{state.sources.map((s) => <tr key={s.id}><td className="font-bold text-white">{s.name}<div className="max-w-xs truncate text-xs font-normal text-slate-500">{s.url || s.fileName || 'Sin referencia'}</div></td><td>{supplierName(state.suppliers, s.supplierId)}</td><td>{s.kind}{s.size ? ` · ${(s.size / 1024).toFixed(1)} KB` : ''}</td><td><Badge value={s.extractionStatus} />{s.extractionError && <div className="mt-1 max-w-xs text-xs text-red-300">{s.extractionError}</div>}</td><td><select aria-label={`Estado de ${s.name}`} className="field" value={s.status} onChange={(e) => update((current) => ({ ...current, sources: current.sources.map((x) => x.id === s.id ? { ...x, status: e.target.value as ReviewStatus } : x) }))}>{statuses.map((x) => <option key={x}>{x}</option>)}</select></td><td className="space-x-2"><button type="button" className="button-secondary" onClick={() => { setSelected(s.id); void review(s); }}>Revisar / extraer</button><button type="button" className="icon-button" aria-label={`Eliminar ${s.name}`} onClick={() => remove(s.id)}><TrashIcon className="h-4 w-4" /></button></td></tr>)}</tbody></table></div> : <EmptyState text="Registra una fuente para iniciar revisión." />}</Panel>{source && <Panel title={`Candidatos de ${source.name}`} subtitle="Edita cada campo, rechaza los que no correspondan y aprueba solo los válidos" action={<div className="flex flex-wrap gap-2"><button type="button" className="button-secondary" onClick={addCandidate}><PlusIcon className="h-4 w-4" /> Agregar manual</button><button type="button" className="button-secondary" onClick={approveAll}><CheckCircleIcon className="h-4 w-4" /> Aprobar los que tienen precio</button><button type="button" className="button-primary" onClick={confirmCandidates}>Importar aprobados al catálogo</button></div>}>{source.extractionStatus === 'Error' && <p className="mb-4 rounded-lg border border-red-300/20 bg-red-400/10 p-3 text-xs text-red-200">{source.extractionError} La aplicación no inventa datos: corrige manualmente o vuelve a intentar.</p>}{source.candidates.length ? <div className="space-y-3">{source.candidates.map((c) => <div key={c.id} className={`rounded-xl border p-3 ${c.status === 'Aprobado' ? 'border-emerald-400/30 bg-emerald-400/5' : c.status === 'Rechazado' ? 'border-white/5 opacity-60' : 'border-white/10'}`}>
  <div className="flex gap-3">
    <div className="h-16 w-16 shrink-0 overflow-hidden rounded-lg border border-white/10 bg-white/5">{c.imageUrl ? <img src={c.imageUrl} alt="" loading="lazy" referrerPolicy="no-referrer" className="h-full w-full object-contain" onError={(event) => { event.currentTarget.style.display = 'none'; }} /> : <span className="flex h-full items-center justify-center text-[10px] text-slate-500">Sin foto</span>}</div>
    <div className="grid min-w-0 flex-1 gap-2 sm:grid-cols-2 lg:grid-cols-4">
      <input aria-label="Nombre candidato" className="field sm:col-span-2" value={c.name} onChange={(e) => editCandidate(c, { name: e.target.value })} placeholder="Nombre del producto" />
      <input aria-label="Código del proveedor" className="field" value={c.sku} onChange={(e) => editCandidate(c, { sku: e.target.value })} placeholder="Código del proveedor" />
      <input aria-label="Precio candidato" className="field" type="number" min="0" step="0.01" value={c.price || ''} placeholder="Precio" onChange={(e) => editCandidate(c, { price: toNumber(e.target.value) })} />
      <input aria-label="Marca candidato" className="field" value={c.brand} onChange={(e) => editCandidate(c, { brand: e.target.value })} placeholder="Marca" />
      <input aria-label="Unidad candidato" className="field" value={c.unit} onChange={(e) => editCandidate(c, { unit: e.target.value })} placeholder="Presentación" />
      <input aria-label="Categoría candidato" className="field" value={c.category} onChange={(e) => editCandidate(c, { category: e.target.value })} placeholder="Categoría" />
      <input aria-label="URL de imagen" className="field" type="url" value={c.imageUrl} onChange={(e) => editCandidate(c, { imageUrl: e.target.value })} placeholder="URL de imagen (https://…)" />
    </div>
  </div>
  <div className="mt-2 flex flex-wrap items-center justify-between gap-2">
    <p className="min-w-0 flex-1 text-[11px] text-slate-500"><span className={c.confidence >= 0.8 ? 'text-emerald-300' : c.confidence >= 0.6 ? 'text-amber-300' : 'text-red-300'}>Confianza {Math.round(c.confidence * 100)}%</span> · {c.notes}{c.fields?.name?.evidence?.[0]?.excerpt ? <> · <span title={c.fields.name.evidence[0].excerpt}>origen: “{c.fields.name.evidence[0].excerpt.slice(0, 80)}{c.fields.name.evidence[0].excerpt.length > 80 ? '…' : ''}”</span></> : null}</p>
    <select aria-label="Estado candidato" className="field" value={c.status} onChange={(e) => editCandidate(c, { status: e.target.value as CandidateStatus })}><option>Pendiente</option><option>Aprobado</option><option>Rechazado</option></select>
  </div>
</div>)}</div> : <EmptyState text="No hay candidatos. Tocá “Revisar / extraer” o agregá productos manualmente." />}</Panel>}</>;
}

function Users({ state, update, notify }: { state: State; update: Mutate; notify: (m: string) => void }) { const [editing, setEditing] = useState<User | null>(null); const active = state.users.filter((u) => u.active).length; const save = () => { if (!editing?.name.trim()) return notify('El nombre es obligatorio'); if (editing.email && !EMAIL_PATTERN.test(editing.email.trim())) return notify('Ingresá un email válido o dejalo vacío'); if (state.users.some((u) => u.id !== editing.id && u.name.trim().toLowerCase() === editing.name.trim().toLowerCase())) return notify('Ya existe un usuario con ese nombre'); editing.name = editing.name.trim(); editing.email = editing.email?.trim(); if (editing.active === false && state.users.find((u) => u.id === editing.id)?.active && active <= 1) return notify('No puedes dejar el sistema sin usuarios activos'); update((current) => ({ ...current, users: current.users.some((u) => u.id === editing.id) ? current.users.map((u) => u.id === editing.id ? editing : u) : [...current.users, editing] })); setEditing(null); notify('Usuario guardado'); }; const remove = (user: User) => { if (active === 1 && user.active) return notify('No puedes eliminar el último usuario activo'); if (window.confirm(`¿Eliminar a ${user.name}? Su nombre se conserva en pedidos, recepciones y pagos ya registrados.`)) { update((current) => ({ ...current, users: current.users.filter((u) => u.id !== user.id) })); notify(`${user.name} eliminado`); } }; return <><Panel title="Usuarios y administración" subtitle="Personas que usan el sistema; quedan registradas como responsables en pedidos, recepciones, pagos y movimientos de stock" action={<button type="button" className="button-primary" onClick={() => setEditing({ id: `usr-${Date.now()}`, name: '', email: '', role: 'Consulta', active: true, createdAt: today })}><PlusIcon className="h-4 w-4" /> Nuevo usuario</button>}><div className="mb-5 grid gap-3 sm:grid-cols-4">{roles.map((role) => <div key={role} className="rounded-xl border border-white/10 p-3"><div className="font-bold text-white">{role}</div><div className="mt-1 text-xs text-slate-400">{role === 'Administrador' ? 'Gestiona usuarios y configuración' : role === 'Compras' ? 'Pedidos y proveedores' : role === 'Recepción' ? 'Recepciones y vencimientos' : 'Consulta de información'}</div></div>)}</div><div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Nombre</th><th>Email</th><th>Rol / permisos demo</th><th>Alta</th><th>Estado</th><th /></tr></thead><tbody>{state.users.map((u) => <tr key={u.id}><td className="font-bold text-white">{u.name}</td><td>{u.email || 'No informado'}</td><td>{u.role}</td><td>{dateEs(u.createdAt)}</td><td><button type="button" aria-label={`${u.active ? 'Desactivar' : 'Activar'} a ${u.name}`} title={u.active ? 'Tocá para desactivar' : 'Tocá para activar'} onClick={() => { if (u.active && active <= 1) return notify('No puedes dejar el sistema sin usuarios activos'); update((current) => ({ ...current, users: current.users.map((x) => x.id === u.id ? { ...x, active: !x.active } : x) })); }}><Badge value={u.active ? 'Activo' : 'Inactivo'} /></button></td><td className="space-x-2"><button type="button" className="button-secondary" onClick={() => setEditing({ ...u })}>Editar</button><button type="button" className="icon-button" aria-label={`Eliminar ${u.name}`} onClick={() => remove(u)}><TrashIcon className="h-4 w-4" /></button></td></tr>)}</tbody></table></div></Panel>{editing && <Panel title={state.users.some((u) => u.id === editing.id) ? 'Editar usuario' : 'Nuevo usuario'} subtitle="El email es opcional"><div className="grid gap-4 sm:grid-cols-4"><Field label="Nombre"><input className="field w-full" value={editing.name} onChange={(e) => setEditing({ ...editing, name: e.target.value })} /></Field><Field label="Email opcional"><input className="field w-full" type="email" value={editing.email || ''} onChange={(e) => setEditing({ ...editing, email: e.target.value })} /></Field><Field label="Rol"><select className="field w-full" value={editing.role} onChange={(e) => setEditing({ ...editing, role: e.target.value as UserRole })}>{roles.map((role) => <option key={role}>{role}</option>)}</select></Field><Field label="Estado"><label className="flex min-h-10 items-center gap-2 rounded-lg border border-white/15 bg-[#0c2330] px-3 text-xs"><input type="checkbox" className="h-4 w-4 accent-cyan-400" checked={editing.active} onChange={(e) => setEditing({ ...editing, active: e.target.checked })} /> Activo</label></Field></div><div className="mt-5 flex gap-2"><button type="button" className="button-primary" onClick={save}>Guardar usuario</button><button type="button" className="button-secondary" onClick={() => setEditing(null)}>Cancelar</button></div></Panel>}</>; }
function Payments({ state, update, notify, exportCsv, userName }: { state: State; update: Mutate; notify: (m: string) => void; exportCsv: () => void; userName: string }) {
  const [supplier, setSupplier] = useState(''); const [status, setStatus] = useState(''); const [cashBox, setCashBox] = useState(''); const [editing, setEditing] = useState<Payment | null>(null); const [pdfId, setPdfId] = useState<string | null>(null);
  const users = state.users.filter((u) => u.active);
  const filtered = [...state.payments].reverse().filter((p) => !p.cancelled && (!supplier || p.supplierId === supplier) && (!status || p.status === status) && (!cashBox || p.cashBox === cashBox));
  const totals = filtered.reduce((a, p) => ({ paid: a.paid + (p.status === 'pagado' ? p.amount : 0), pending: a.pending + (p.status === 'pendiente' || p.status === 'parcial' ? p.amount : 0), overdue: a.overdue + (p.status === 'vencido' ? p.amount : 0) }), { paid: 0, pending: 0, overdue: 0 });
  const byBox = cashBoxes.map((box) => ({ box, total: state.payments.filter((p) => !p.cancelled && p.status === 'pagado' && p.cashBox === box).reduce((sum, p) => sum + p.amount, 0) }));
  const isNew = Boolean(editing && !state.payments.some((p) => p.id === editing.id));
  const blank = (): Payment => ({ id: `new-${Date.now()}`, supplierId: state.suppliers.find((s) => s.active)?.id || '', orderId: undefined, amount: 0, date: getLocalDateISO(), method: 'efectivo', status: 'pagado', reference: '', notes: '', responsible: userName, cashBox: cashBoxes[0] });
  const supplierOrders = editing ? state.orders.filter((o) => o.supplierId === editing.supplierId && orderStage(o.status) !== 'cancelado') : [];
  const save = () => {
    if (!editing?.supplierId) return notify('Elegí el proveedor');
    if (!(editing.amount > 0)) return notify('Ingresá un monto mayor a 0');
    if (!editing.date) return notify('Ingresá la fecha del pago');
    if (editing.method === 'efectivo' && !editing.cashBox) return notify('Indicá de qué caja salió el efectivo');
    update((current) => { const exists = current.payments.some((p) => p.id === editing.id); const saved = { ...editing, reference: editing.reference.trim(), notes: editing.notes.trim(), id: exists ? editing.id : nextSequentialId('PAG', current.payments.map((p) => p.id)) }; return { ...current, payments: exists ? current.payments.map((p) => p.id === editing.id ? saved : p) : [...current.payments, saved] }; });
    setEditing(null); notify(isNew ? 'Pago registrado' : 'Pago actualizado');
  };
  const voidPayment = (payment: Payment) => { if (!window.confirm(`¿Anular el pago ${payment.id} por ${money(payment.amount)}? Queda en el historial como anulado.`)) return; update((current) => ({ ...current, payments: current.payments.map((p) => p.id === payment.id ? { ...p, cancelled: true, notes: `${p.notes ? `${p.notes} · ` : ''}Anulado por ${userName}` } : p) })); notify(`Pago ${payment.id} anulado`); };
  return <>
    <div className="mb-6 grid grid-cols-2 gap-3 sm:gap-4 xl:grid-cols-3"><Metric title="Pagado" value={money(totals.paid)} note="Pagos confirmados" color="green" /><Metric title="Pendiente" value={money(totals.pending)} note="Pendiente y parcial" color="amber" /><Metric title="Vencido" value={money(totals.overdue)} note="Requiere gestión" color="red" /></div>
    <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">{byBox.map(({ box, total }) => <button key={box} type="button" onClick={() => setCashBox(cashBox === box ? '' : box)} aria-pressed={cashBox === box} className={`card p-4 text-left transition ${cashBox === box ? 'border-cyan-300/60' : 'hover:border-white/25'}`}><div className="text-xs font-semibold text-slate-400">{box}</div><div className="mt-1 truncate text-lg font-bold text-white">{money(total)}</div><div className="text-[11px] text-slate-500">pagado desde esta caja</div></button>)}</div>
    {editing && <div className="mb-6"><Panel title={isNew ? 'Nuevo pago' : `Editar pago ${editing.id}`} subtitle="Indicá de qué caja salió el dinero; el responsable queda registrado"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
      <Field label="Proveedor *"><select className="field w-full" value={editing.supplierId} onChange={(e) => setEditing({ ...editing, supplierId: e.target.value, orderId: undefined })}>{state.suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}{s.active ? '' : ' (desactivado)'}</option>)}</select></Field>
      <Field label="Pedido asociado"><select className="field w-full" value={editing.orderId || ''} onChange={(e) => setEditing({ ...editing, orderId: e.target.value || undefined })}><option value="">Sin pedido</option>{supplierOrders.map((o) => <option key={o.id} value={o.id}>{o.id} · {money(orderTotal(o))}</option>)}</select></Field>
      <Field label="Monto *"><input className="field w-full" type="number" inputMode="decimal" min="0" value={editing.amount || ''} placeholder="0" onChange={(e) => setEditing({ ...editing, amount: toNumber(e.target.value) })} /></Field>
      <Field label="Fecha *"><input className="field w-full" type="date" value={editing.date} onChange={(e) => setEditing({ ...editing, date: e.target.value })} /></Field>
      <Field label="Caja"><select className="field w-full" value={editing.cashBox || ''} onChange={(e) => setEditing({ ...editing, cashBox: e.target.value || undefined })}><option value="">Sin caja</option>{cashBoxes.map((box) => <option key={box}>{box}</option>)}</select></Field>
      <Field label="Método"><select className="field w-full" value={editing.method} onChange={(e) => setEditing({ ...editing, method: e.target.value as PaymentMethod })}>{paymentMethods.map((x) => <option key={x}>{x}</option>)}</select></Field>
      <Field label="Estado"><select className="field w-full" value={editing.status} onChange={(e) => setEditing({ ...editing, status: e.target.value as PaymentStatus })}>{paymentStatuses.map((x) => <option key={x}>{x}</option>)}</select></Field>
      <Field label="Responsable"><select className="field w-full" value={editing.responsible || ''} onChange={(e) => setEditing({ ...editing, responsible: e.target.value })}>{users.map((u) => <option key={u.id}>{u.name}</option>)}{editing.responsible && !users.some((u) => u.name === editing.responsible) && <option>{editing.responsible}</option>}</select></Field>
      <Field label="Referencia / comprobante"><input className="field w-full" value={editing.reference} placeholder="N.º de transferencia, recibo…" onChange={(e) => setEditing({ ...editing, reference: e.target.value })} /></Field>
      <div className="sm:col-span-2 lg:col-span-3"><Field label="Notas"><input className="field w-full" value={editing.notes} onChange={(e) => setEditing({ ...editing, notes: e.target.value })} /></Field></div>
    </div><div className="mt-5 flex flex-wrap justify-end gap-2"><button type="button" className="button-secondary" onClick={() => setEditing(null)}>Cancelar</button><button type="button" className="button-primary" onClick={save}><CheckCircleIcon className="h-4 w-4" /> Guardar pago</button></div></Panel></div>}
    <Panel title="Pagos" subtitle="Cada pago con su caja, responsable y comprobante en PDF" action={<div className="flex flex-wrap gap-2"><select aria-label="Filtrar proveedor de pagos" className="field" value={supplier} onChange={(e) => setSupplier(e.target.value)}><option value="">Todos los proveedores</option>{state.suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select><select aria-label="Filtrar estado de pagos" className="field" value={status} onChange={(e) => setStatus(e.target.value)}><option value="">Todos los estados</option>{paymentStatuses.map((x) => <option key={x}>{x}</option>)}</select><select aria-label="Filtrar por caja" className="field" value={cashBox} onChange={(e) => setCashBox(e.target.value)}><option value="">Todas las cajas</option>{cashBoxes.map((box) => <option key={box}>{box}</option>)}</select><button type="button" className="button-primary" onClick={() => setEditing(blank())}><PlusIcon className="h-4 w-4" /> Nuevo pago</button><button type="button" className="button-secondary" onClick={exportCsv}><ArrowDownTrayIcon className="h-4 w-4" /> CSV</button></div>}>
      {filtered.length ? <><ul className="space-y-3 md:hidden">{filtered.map((p) => <li key={p.id} className="rounded-xl border border-white/10 p-4"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="font-bold text-white">{money(p.amount)}</div><div className="mt-1 text-xs text-slate-400">{p.id} · {supplierName(state.suppliers, p.supplierId)} · {dateEs(p.date)}</div><div className="mt-1 text-xs text-slate-400">{p.cashBox || 'Sin caja'} · <span className="capitalize">{p.method}</span>{p.responsible ? ` · ${p.responsible}` : ''}</div></div><Badge value={p.status} /></div><div className="mt-3 flex flex-wrap gap-2"><button type="button" className="button-primary" onClick={() => setPdfId(p.id)}><DocumentArrowDownIcon className="h-4 w-4" /> PDF</button><button type="button" className="button-secondary" onClick={() => setEditing({ ...p })}><PencilSquareIcon className="h-4 w-4" /> Editar</button><button type="button" className="icon-button text-red-300" onClick={() => voidPayment(p)} aria-label={`Anular pago ${p.id}`}><TrashIcon className="h-4 w-4" /></button></div></li>)}</ul><div className="hidden overflow-x-auto md:block"><table className="data-table"><thead><tr><th>ID / proveedor</th><th>Monto</th><th>Fecha</th><th>Caja / método</th><th>Estado</th><th>Responsable</th><th>Acciones</th></tr></thead><tbody>{filtered.map((p) => <tr key={p.id}>
        <td className="font-bold text-white">{p.id}<div className="text-xs font-normal">{supplierName(state.suppliers, p.supplierId)}{p.orderId ? ` · ${p.orderId}` : ''}</div></td>
        <td className="whitespace-nowrap font-semibold text-white">{money(p.amount)}</td>
        <td className="whitespace-nowrap">{dateEs(p.date)}</td>
        <td>{p.cashBox || <span className="text-slate-500">Sin caja</span>}<div className="text-xs capitalize text-slate-500">{p.method}</div></td>
        <td><Badge value={p.status} /></td>
        <td>{p.responsible || 'No asignado'}</td>
        <td><div className="flex flex-wrap gap-2"><button type="button" className="button-primary" onClick={() => setPdfId(p.id)} aria-label={`Generar PDF del pago ${p.id}`}><DocumentArrowDownIcon className="h-4 w-4" /> PDF</button><button type="button" className="button-secondary" onClick={() => setEditing({ ...p })} aria-label={`Editar pago ${p.id}`}><PencilSquareIcon className="h-4 w-4" /> Editar</button><button type="button" className="icon-button text-red-300" onClick={() => voidPayment(p)} aria-label={`Anular pago ${p.id}`}><TrashIcon className="h-4 w-4" /></button></div></td>
      </tr>)}</tbody></table></div></> : <EmptyState text="No hay pagos para este filtro." />}
    </Panel>
    <PaymentPdf state={state} paymentId={pdfId} onClose={() => setPdfId(null)} />
  </>;
}
function Economy({ state, onNavigate }: { state: State; onNavigate: (s: Section) => void }) {
  const totals = finance(state);
  const bySupplier = state.suppliers.map((supplier) => { const orders = state.orders.filter((o) => o.supplierId === supplier.id && orderStage(o.status) !== 'cancelado'); const purchased = orders.reduce((sum, o) => sum + orderTotal(o), 0); const paid = state.payments.filter((p) => p.supplierId === supplier.id && !p.cancelled && p.status === 'pagado').reduce((sum, p) => sum + p.amount, 0); return { supplier, purchased, paid, balance: Math.max(purchased - paid, 0), orders: orders.length }; }).filter((row) => row.purchased || row.paid).sort((a, b) => b.balance - a.balance);
  const byBox = cashBoxes.map((box) => ({ box, total: state.payments.filter((p) => !p.cancelled && p.status === 'pagado' && p.cashBox === box).reduce((sum, p) => sum + p.amount, 0) }));
  return <><div className="grid grid-cols-2 gap-3 sm:gap-4 xl:grid-cols-4"><Metric title="Comprado" value={money(totals.purchased)} note="Pedidos no cancelados" color="amber" /><Metric title="Recibido" value={money(totals.received)} note="Valor de lo que llegó" color="green" /><Metric title="Pagado" value={money(totals.paid)} note="Pagos confirmados" /><Metric title="Saldo" value={money(totals.balance)} note="Comprado menos pagado" color="red" onClick={() => onNavigate('Pagos')} /></div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.6fr_1fr]"><Panel title="Por proveedor" subtitle="Cuánto se compró, pagó y se debe a cada uno">{bySupplier.length ? <div className="overflow-x-auto"><table className="data-table"><thead><tr><th>Proveedor</th><th>Pedidos</th><th>Comprado</th><th>Pagado</th><th>Saldo</th></tr></thead><tbody>{bySupplier.map((row) => <tr key={row.supplier.id}><td className="font-semibold text-white">{row.supplier.name}</td><td>{row.orders}</td><td>{money(row.purchased)}</td><td className="text-emerald-300">{money(row.paid)}</td><td className={row.balance ? 'font-semibold text-amber-300' : ''}>{money(row.balance)}</td></tr>)}</tbody></table></div> : <EmptyState text="Todavía no hay compras registradas." />}</Panel>
    <Panel title="Pagos por caja" subtitle="Dinero pagado desde cada caja"><ul className="space-y-2">{byBox.map(({ box, total }) => <li key={box} className="flex items-center justify-between rounded-xl border border-white/10 px-4 py-3"><span className="text-sm text-slate-300">{box}</span><span className="font-bold text-white">{money(total)}</span></li>)}</ul></Panel></div></>;
}
function History({ state }: { state: State }) {
  const [type, setType] = useState(''); const [query, setQuery] = useState('');
  const productName = (id: string) => state.products.find((p) => p.id === id)?.name || 'Producto eliminado';
  const events = [
    ...state.orders.flatMap((o) => [{ date: o.requestedAt || o.createdAt, type: 'Pedido', title: `Pedido ${o.id} creado`, detail: `${supplierName(state.suppliers, o.supplierId)} · ${money(orderTotal(o))}${o.requester ? ` · ${o.requester}` : ''}` }, ...(o.events || []).filter((e) => e.status !== 'Preparado').map((e) => ({ date: e.at, type: 'Pedido', title: `Pedido ${o.id}: ${stageLabels[orderStage(e.status)]}`, detail: `${supplierName(state.suppliers, o.supplierId)} · ${e.by}${e.note ? ` · ${e.note}` : ''}` }))]),
    ...state.receptions.map((r) => ({ date: r.arrivedAt || r.createdAt, type: 'Recepción', title: `Recepción ${r.orderId}`, detail: `${r.arrivedAt ? 'Llegada confirmada' : 'Recepción abierta'}${r.responsible ? ` · ${r.responsible}` : ''} · ${r.lines.filter((l) => l.status !== 'received').length} diferencia(s)` })),
    ...state.payments.map((p) => ({ date: p.date, type: 'Pago', title: `Pago ${p.id}${p.cancelled ? ' (anulado)' : ''}`, detail: `${money(p.amount)} · ${supplierName(state.suppliers, p.supplierId)}${p.cashBox ? ` · ${p.cashBox}` : ''} · ${p.status}` })),
    ...state.stockMovements.map((m) => ({ date: m.date, type: 'Stock', title: `${productName(m.productId)}: ${m.before} → ${m.after}`, detail: `${m.quantity > 0 ? '+' : ''}${m.quantity} · ${m.reason || m.type} · ${m.user}` })),
    ...state.sources.map((s) => ({ date: s.extractedAt || s.date, type: 'Fuente', title: s.name, detail: `${s.kind} · ${supplierName(state.suppliers, s.supplierId)} · ${s.status}` })),
  ].filter((e) => e.date && (!type || e.type === type) && (!query.trim() || `${e.title} ${e.detail}`.toLowerCase().includes(query.trim().toLowerCase()))).sort((a, b) => b.date.localeCompare(a.date));
  const when = (value: string) => value.length > 10 ? new Date(value).toLocaleString('es-AR', { dateStyle: 'short', timeStyle: 'short' }) : dateEs(value);
  return <Panel title="Historial" subtitle="Todo lo que pasó: pedidos, recepciones, pagos, stock y fuentes" action={<div className="flex flex-wrap gap-2"><input aria-label="Buscar en historial" className="field w-full sm:w-48" placeholder="Buscar…" value={query} onChange={(e) => setQuery(e.target.value)} /><select aria-label="Filtrar historial" className="field" value={type} onChange={(e) => setType(e.target.value)}><option value="">Todo</option>{['Pedido', 'Recepción', 'Pago', 'Stock', 'Fuente'].map((item) => <option key={item}>{item}</option>)}</select></div>}>{events.length ? <ol className="space-y-2">{events.slice(0, 300).map((e, i) => <li key={`${e.type}-${e.title}-${i}`} className="flex gap-3 rounded-lg border border-white/10 p-3"><span className="w-24 shrink-0 text-xs text-cyan-300 sm:w-32">{when(e.date)}</span><div className="min-w-0"><div className="font-semibold text-white"><span className="badge-muted mr-2">{e.type}</span>{e.title}</div><div className="mt-1 text-xs text-slate-400">{e.detail}</div></div></li>)}</ol> : <EmptyState text="No hay eventos para este filtro." />}</Panel>;
}
function paymentLabel(state: State, orderId: string) { const payments = state.payments.filter((p) => p.orderId === orderId && !p.cancelled); if (payments.some((p) => p.status === 'pagado')) return 'pagado'; if (payments.some((p) => p.status === 'vencido')) return 'vencido'; if (payments.length) return 'parcial'; return 'pendiente'; }
function finance(state: State) { const orders = state.orders.filter((o) => orderStage(o.status) !== 'cancelado'); const purchased = orders.reduce((a, o) => a + orderTotal(o), 0); const orderIds = new Set(orders.map((o) => o.id)); const received = state.receptions.filter((r) => orderIds.has(r.orderId)).reduce((total, r) => { const order = state.orders.find((o) => o.id === r.orderId); return total + (order ? r.lines.reduce((sum, line) => sum + line.received * (order.lines.find((x) => x.id === line.orderLineId)?.price || 0), 0) : 0); }, 0); const paid = state.payments.filter((p) => !p.cancelled && p.status === 'pagado').reduce((a, p) => a + p.amount, 0); return { purchased, received, paid, balance: Math.max(purchased - paid, 0) }; }
